//! 🧪️ Original object headers order incrementally and the borrowed intrinsic record matches the exact existing wire bridge.
use super::*;
fn ordered(value:&mut DslValue){match value{DslValue::Object(rows)=>{rows.sort_by(|left,right|left.0.as_bytes().cmp(right.0.as_bytes()));for(_,value)in rows{ordered(value)}},DslValue::Array(rows)=>rows.iter_mut().for_each(ordered),_=>{}}}
fn reversed(value:&mut DslValue){match value{DslValue::Object(rows)=>{rows.reverse();for(_,value)in rows{reversed(value)}},DslValue::Array(rows)=>rows.iter_mut().for_each(reversed),_=>{}}}
fn order_tree(value:&DslValue)->serde_json::Value{match value{DslValue::Object(rows)=>serde_json::json!(["object",rows.iter().map(|(key,value)|serde_json::json!([key,order_tree(value)])).collect::<Vec<_>>()]),DslValue::Array(rows)=>serde_json::json!(["array",rows.iter().map(order_tree).collect::<Vec<_>>()]),_=>serde_json::json!(["scalar",serde_json::to_value(value).unwrap()])}}
fn pointers(value:&DslValue,output:&mut Vec<usize>){match value{DslValue::Object(rows)=>{output.push(rows.as_ptr()as usize);for(key,value)in rows{output.push(key.as_ptr()as usize);pointers(value,output)}},DslValue::Array(rows)=>{output.push(rows.as_ptr()as usize);for value in rows{pointers(value,output)}},DslValue::String(text)=>output.push(text.as_ptr()as usize),_=>{}}}
#[test]
fn original_wire_value_orders_unique_headers_and_borrows_canonical_pack(){let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();let mut values:Vec<DslValue>=law["cases"].as_array().unwrap().iter().map(DslValue::from).collect();values.push(DslValue::Object(vec![(format!("{}z","α".repeat(70)),DslValue::String("a".repeat(8197))),(format!("{}a","α".repeat(70)),DslValue::Array(vec![DslValue::String("a".repeat(8197))]))]));for (case,source) in values.into_iter().enumerate(){for cut in law["cancelAfter"].as_array().unwrap().iter().map(|cut|Some(cut.as_u64().unwrap()as usize)).chain([None]){let mut value=Box::new(source.clone());reversed(&mut value);let mut expected=(*value).clone();ordered(&mut expected);let mut before=Vec::new();pointers(&value,&mut before);before.sort_unstable();let mut cursor=WireValueKeyOrderCursor::default();for index in 0..262144{if cut==Some(index){break}if cursor.is_complete(){break}let d=cursor.demands(&value,19).unwrap();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:d.depth};for denied in [RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..g},RetainedCloneGrant{maximum_depth:d.depth-1,..g}]{let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.advance(&mut value,19,denied).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(cursor.demands(&value,19).unwrap(),d);}let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.advance(&mut value,19,g).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(step.progress().fits(g));assert!(index<262143);}if cut.is_none(){assert!(cursor.is_complete());assert_eq!(*value,expected);if let Some(expected)=law["expectedOrders"].get(case){assert_eq!(order_tree(&value),*expected);}let borrowed=BorrowedWireValue::new(&value);let mut encoder=pack::record::BorrowedProjectedPackCursor::default();let mut actual=Vec::new();let mut output=[0;64];for index in 0..262144{let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:encoder.next_minimum_copy_bytes().max(64),maximum_capacity_bytes:encoder.next_capacity_byte_demand().unwrap(),maximum_release_bytes:0,maximum_depth:encoder.next_advance_depth_demand().unwrap()};let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||encoder.advance(&borrowed,BorrowedWireValue::RECORD,&mut output,g).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress.retained_capacity_bytes,step.progress.released_bytes));actual.extend_from_slice(&output[..step.written_bytes]);if step.complete{break}assert!(index<262143);}assert_eq!(actual,super::super::encode_wire_value(&value));while !encoder.terminal_is_empty(){let d=encoder.retirement_demands().unwrap();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||encoder.close(g).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress.retained_capacity_bytes,step.progress.released_bytes));}}let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.close());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(cursor.terminal_is_empty());let mut after=Vec::new();pointers(&value,&mut after);after.sort_unstable();assert_eq!(before,after);}}}
